create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade, name text not null check(length(name) between 1 and 80), role text not null check(role in ('coach','student')), grade text not null default '', stage int not null default 1 check(stage between 1 and 3));
create table public.coach_student_assignments(coach_id uuid references profiles,student_id uuid references profiles,primary key(coach_id,student_id));
create table public.weekly_plans(id uuid primary key default gen_random_uuid(),student_id uuid not null references profiles,week_start date not null check(extract(isodow from week_start)=1),goal text not null default '',confirmed boolean not null default false,unique(student_id,week_start),unique(id,student_id));
create table public.tasks(id uuid primary key default gen_random_uuid(),student_id uuid not null references profiles,plan_id uuid not null,title text not null check(length(title) between 1 and 200),description text not null default '' check(length(description)<=2000),subject text not null check(subject in ('국어','영어','수학','과학','사회','역사','기타')),due_date date not null,status text not null default 'unreported' check(status in ('unreported','done','incomplete')),cancelled boolean not null default false,foreign key(plan_id,student_id) references weekly_plans(id,student_id));
create table public.coaching_logs(id uuid primary key default gen_random_uuid(),student_id uuid not null references profiles,week_start date not null,result text not null default '',observation text not null default '',cause text not null default '',strategy text not null default '',priority text not null default '',internal_note text not null default '',unique(student_id,week_start));
create table public.published_feedback(student_id uuid references profiles,week_start date,body text not null,primary key(student_id,week_start));
create table public.sharing_preferences(student_id uuid primary key references profiles,weekly boolean not null default false,monthly boolean not null default false,student_agreed boolean not null default false,legal_verified boolean not null default false);
create table public.reports(id uuid primary key default gen_random_uuid(),student_id uuid not null references profiles,kind text not null check(kind in ('weekly','monthly')),period_start date not null,period_end date not null,body text not null,approved boolean not null default false,created_at timestamptz not null default now(),check(period_end>=period_start));
create table public.audit_logs(id bigint generated always as identity primary key,student_id uuid not null,actor uuid,entity text not null,old_data jsonb,new_data jsonb,created_at timestamptz not null default now());
create function public.is_coach(s uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from coach_student_assignments a join profiles p on p.id=a.coach_id where a.student_id=s and a.coach_id=auth.uid() and p.role='coach')$$;
create function public.can_read(s uuid) returns boolean language sql stable security definer set search_path=public as $$select coalesce(auth.uid()=s,false) or public.is_coach(s)$$;
alter table profiles enable row level security;
create policy profile_read on profiles for select to authenticated using(id=auth.uid() or is_coach(id) or exists(select 1 from coach_student_assignments where student_id=auth.uid() and coach_id=profiles.id));
alter table coach_student_assignments enable row level security;
create policy assignment_read on coach_student_assignments for select to authenticated using(coach_id=auth.uid() or student_id=auth.uid());
do $$declare t text;begin foreach t in array array['weekly_plans','tasks','published_feedback','sharing_preferences'] loop execute format('alter table %I enable row level security',t);execute format('create policy read_own on %I for select to authenticated using(public.can_read(student_id))',t);end loop;foreach t in array array['coaching_logs','reports','audit_logs'] loop execute format('alter table %I enable row level security',t);execute format('create policy coach_only on %I for select to authenticated using(public.is_coach(student_id))',t);end loop;end$$;
-- No client writes to tables: all mutations pass through checked RPCs below.
revoke insert,update,delete on all tables in schema public from anon,authenticated;
grant select on all tables in schema public to authenticated;
create function public.audit_change() returns trigger language plpgsql security definer set search_path=public as $$begin insert into audit_logs(student_id,actor,entity,old_data,new_data) values(coalesce(new.student_id,old.student_id),auth.uid(),tg_table_name,case when tg_op='INSERT' then null else to_jsonb(old) end,to_jsonb(new));return new;end$$;
do $$declare t text;begin foreach t in array array['weekly_plans','tasks','coaching_logs','published_feedback','sharing_preferences','reports'] loop execute format('create trigger audit after insert or update on %I for each row execute function audit_change()',t);end loop;end$$;
create function public.save_plan(s uuid,w date,g text,confirm_plan boolean default false) returns uuid language plpgsql security definer set search_path=public as $$declare p weekly_plans;begin if auth.uid() is null then raise exception '인증 필요';end if;if not is_coach(s) and not (auth.uid()=s and exists(select 1 from profiles where id=s and stage=3) and not confirm_plan) then raise exception '계획 작성 권한이 없습니다';end if;select * into p from weekly_plans where student_id=s and week_start=w for update;if p.confirmed and not is_coach(s) then raise exception '확정 계획은 코치가 수정합니다';end if;insert into weekly_plans(student_id,week_start,goal,confirmed) values(s,w,left(g,2000),confirm_plan) on conflict(student_id,week_start) do update set goal=excluded.goal,confirmed=excluded.confirmed returning id into p.id;return p.id;end$$;
create function public.save_task(p uuid,t uuid,title_text text,detail text,sub text,d date,cancel_task boolean default false) returns void language plpgsql security definer set search_path=public as $$declare plan weekly_plans;st int;previous tasks;begin if auth.uid() is null then raise exception '인증 필요';end if;select * into plan from weekly_plans where id=p for update;select stage into st from profiles where id=auth.uid();if plan.id is null or not (is_coach(plan.student_id) or (auth.uid()=plan.student_id and st>=2 and (st=2 or not plan.confirmed))) then raise exception '과제 수정 권한이 없습니다';end if;if d<plan.week_start or d>plan.week_start+6 then raise exception '같은 주의 날짜를 선택하세요';end if;if t is null then if not is_coach(plan.student_id) and st<>3 then raise exception '과제 추가는 코치 또는 3단계 초안에서 가능합니다';end if;insert into tasks(student_id,plan_id,title,description,subject,due_date) values(plan.student_id,p,title_text,detail,sub,d);else select * into previous from tasks where id=t and plan_id=p;if previous.id is null then raise exception '과제를 찾을 수 없습니다';end if;if not is_coach(plan.student_id) and st=2 and (title_text<>previous.title or detail<>previous.description or sub<>previous.subject or cancel_task<>previous.cancelled) then raise exception '학생은 날짜 배분만 수정할 수 있습니다';end if;update tasks set title=title_text,description=detail,subject=sub,due_date=d,cancelled=cancel_task where id=t and plan_id=p;end if;end$$;
create function public.check_task(t uuid,value text) returns void language plpgsql security definer set search_path=public as $$begin update tasks set status=value where id=t and student_id=auth.uid() and not cancelled and due_date<=(now() at time zone 'Asia/Seoul')::date;if not found then raise exception '본인의 오늘 또는 과거 과제만 기록할 수 있습니다';end if;end$$;
create function public.save_coaching(s uuid,w date,fields jsonb,feedback text) returns void language plpgsql security definer set search_path=public as $$begin if auth.uid() is null then raise exception '인증 필요';end if;if not is_coach(s) then raise exception '권한 없음';end if;insert into coaching_logs(student_id,week_start,result,observation,cause,strategy,priority,internal_note) values(s,w,fields->>'result',fields->>'observation',fields->>'cause',fields->>'strategy',fields->>'priority',fields->>'internal_note') on conflict(student_id,week_start) do update set result=excluded.result,observation=excluded.observation,cause=excluded.cause,strategy=excluded.strategy,priority=excluded.priority,internal_note=excluded.internal_note;insert into published_feedback values(s,w,left(feedback,10000)) on conflict(student_id,week_start) do update set body=excluded.body;end$$;
create function public.set_stage(s uuid,n int) returns void language plpgsql security definer set search_path=public as $$declare old profiles;begin if auth.uid() is null then raise exception '인증 필요';end if;if not is_coach(s) then raise exception '권한 없음';end if;select * into old from profiles where id=s;update profiles set stage=n where id=s;insert into audit_logs(student_id,actor,entity,old_data,new_data) values(s,auth.uid(),'stage',to_jsonb(old),jsonb_build_object('stage',n));end$$;
create function public.set_sharing(s uuid,w boolean,m boolean,agreed boolean,legal boolean) returns void language plpgsql security definer set search_path=public as $$begin if not can_read(s) then raise exception '권한 없음';end if;insert into sharing_preferences(student_id) values(s) on conflict do nothing;if auth.uid()=s then update sharing_preferences set student_agreed=agreed where student_id=s;elsif is_coach(s) then update sharing_preferences set weekly=w,monthly=m,legal_verified=legal where student_id=s;end if;end$$;
create function public.save_report(s uuid,k text,a date,b date,content text,r uuid default null,approve boolean default false) returns uuid language plpgsql security definer set search_path=public as $$declare rid uuid;begin if auth.uid() is null then raise exception '인증 필요';end if;if not is_coach(s) then raise exception '권한 없음';end if;if approve and not exists(select 1 from sharing_preferences where student_id=s and student_agreed and legal_verified and case when k='weekly' then weekly else monthly end) then raise exception '학생 공유 의사·법적 요건·기간별 허용을 확인하세요';end if;if r is null then insert into reports(student_id,kind,period_start,period_end,body,approved) values(s,k,a,b,left(content,20000),approve) returning id into rid;else update reports set body=left(content,20000),approved=approve where id=r and student_id=s and kind=k and period_start=a and period_end=b returning id into rid;end if;return rid;end$$;
create function public.export_report(r uuid) returns text language plpgsql security definer set search_path=public as $$declare result text;begin select body into result from reports r1 join sharing_preferences p using(student_id) where r1.id=r and is_coach(r1.student_id) and r1.approved and p.student_agreed and p.legal_verified and case when r1.kind='weekly' then p.weekly else p.monthly end;if result is null then raise exception '승인 및 공유 동의가 필요합니다';end if;return result;end$$;
revoke execute on all functions in schema public from public,anon;
grant execute on all functions in schema public to authenticated;
-- Realtime is a convenience; the app also polls, so missed events recover.
alter publication supabase_realtime add table tasks;



-- Deployment hardening (also applied as remote follow-up migrations).
create index if not exists assignments_student_idx on public.coach_student_assignments(student_id);
create index if not exists tasks_student_date_idx on public.tasks(student_id,due_date);
create index if not exists tasks_plan_student_idx on public.tasks(plan_id,student_id);
create index if not exists reports_student_period_idx on public.reports(student_id,period_start);
create index if not exists audit_student_id_idx on public.audit_logs(student_id,id desc);
alter policy profile_read on public.profiles using(id=(select auth.uid()) or is_coach(id) or exists(select 1 from coach_student_assignments where student_id=(select auth.uid()) and coach_id=profiles.id));
alter policy assignment_read on public.coach_student_assignments using(coach_id=(select auth.uid()) or student_id=(select auth.uid()));
revoke execute on function public.audit_change() from authenticated;
revoke all on public.profiles, public.coach_student_assignments, public.weekly_plans, public.tasks, public.coaching_logs, public.published_feedback, public.sharing_preferences, public.reports, public.audit_logs from anon,authenticated;
grant select on public.profiles, public.coach_student_assignments, public.weekly_plans, public.tasks, public.coaching_logs, public.published_feedback, public.sharing_preferences, public.reports, public.audit_logs to authenticated;
grant select,insert,update,delete on public.profiles, public.coach_student_assignments, public.weekly_plans, public.tasks, public.coaching_logs, public.published_feedback, public.sharing_preferences, public.reports, public.audit_logs to service_role;
grant usage,select on sequence public.audit_logs_id_seq to service_role;
